import type { Metadata } from "next";
import { Manrope } from "next/font/google";
import Script from "next/script";
import { ConditionalShell } from "@/components/layout/ConditionalShell";
import { QueryProvider } from "@/components/layout/QueryProvider";
import { ScrollProgress } from "@/components/layout/ScrollProgress";
import { ServiceWorkerRegister } from "@/components/layout/ServiceWorkerRegister";
import { ThemeProvider } from "@/components/layout/ThemeProvider";
import { OfflineBanner } from "@/components/shared/OfflineBanner";
import { AnalyticsTracker } from "@/components/shared/AnalyticsTracker";
import { SITE_CONFIG } from "@/lib/constants";
import { organizationJsonLd } from "@/lib/seo";
import "./globals.css";

const manrope = Manrope({
  variable: "--font-manrope",
  subsets: ["latin"],
  display: "swap",
});

export const metadata: Metadata = {
  metadataBase: new URL(SITE_CONFIG.url),
  title: {
    default: `${SITE_CONFIG.name} | Technology-Enabled Education Solutions`,
    template: `%s | ${SITE_CONFIG.name}`,
  },
  description: SITE_CONFIG.description,
  applicationName: SITE_CONFIG.name,
  generator: "Next.js",
  category: "education",
  keywords: [
    "EdTech",
    "university solutions",
    "school STEM",
    "vocational education",
    "AI Academy",
    "industry academia collaboration",
    "CITIS InfoTech",
  ],
  authors: [{ name: SITE_CONFIG.name, url: SITE_CONFIG.url }],
  creator: SITE_CONFIG.name,
  publisher: SITE_CONFIG.legalName,
  manifest: "/manifest.json",
  icons: {
    icon: [
      { url: "/icons/icon-192.svg", type: "image/svg+xml", sizes: "192x192" },
      { url: "/icons/icon-512.svg", type: "image/svg+xml", sizes: "512x512" },
    ],
    apple: [{ url: "/icons/icon-192.svg", sizes: "192x192", type: "image/svg+xml" }],
  },
  openGraph: {
    type: "website",
    locale: "en_IN",
    url: SITE_CONFIG.url,
    siteName: SITE_CONFIG.name,
    title: `${SITE_CONFIG.name} | Technology-Enabled Education Solutions`,
    description: SITE_CONFIG.description,
    images: [{ url: "/icons/icon-512.svg", width: 512, height: 512, alt: SITE_CONFIG.name }],
  },
  twitter: {
    card: "summary_large_image",
    title: `${SITE_CONFIG.name} | Technology-Enabled Education Solutions`,
    description: SITE_CONFIG.description,
    images: ["/icons/icon-512.svg"],
  },
  robots: {
    index: true,
    follow: true,
    googleBot: { index: true, follow: true, "max-image-preview": "large", "max-snippet": -1, "max-video-preview": -1 },
  },
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  const jsonLd = organizationJsonLd();
  const zendeskKey = process.env.NEXT_PUBLIC_ZENDESK_KEY?.trim();
  return (
    <html lang="en-IN" suppressHydrationWarning>
      <body className={`${manrope.variable} antialiased`}>
        <ThemeProvider>
          <QueryProvider>
            <ScrollProgress />
            <OfflineBanner />
            <AnalyticsTracker />
            <ConditionalShell>{children}</ConditionalShell>
            <ServiceWorkerRegister />
            {zendeskKey ? (
              <Script
                id="zendesk-web-widget"
                src={`https://static.zdassets.com/ekr/snippet.js?key=${encodeURIComponent(zendeskKey)}`}
                strategy="afterInteractive"
              />
            ) : null}
          </QueryProvider>
        </ThemeProvider>
        <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd).replace(/</g, "\\u003c") }} />
      </body>
    </html>
  );
}
